const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const africa = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017")
      .filter(ee.Filter.eq('continent', 'Africa'));

    const year1 = 2003;
    const year2 = 2019;
    const threshold_sq_km = 400000; // The threshold in the question

    // 2. Data Acquisition & Check (MODIS Land Cover Type Yearly Global 500m)
    // Using Land_Cover_Type_1 (IGBP classification)
    // Class 12: Croplands
    const modisCollection = ee.ImageCollection("MODIS/051/MCD12Q1");

    const getCroplandArea = (year, geometry) => {
      const image = modisCollection
        .filter(ee.Filter.calendarRange(year, year, 'year'))
        .first();

      if (!image) {
        return null; // No image found for the year
      }

      // Select IGBP classification band
      const landCover = image.select('Land_Cover_Type_1');

      // Create a binary mask for croplands (Class 12)
      const croplandMask = landCover.eq(12); // Class 12: Croplands
      // Multiply by pixel area to get area in square meters for each pixel
      const croplandAreaImage = croplandMask.multiply(ee.Image.pixelArea());

      // Calculate the sum of cropland area in square meters
      // Use a coarser scale (e.g., 5000m) for continental calculation to prevent memory errors
      // and ensure a reasonable computation time.
      const stats = croplandAreaImage.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: 5000, // MODIS resolution is 500m, using 5000m for continental sum
        maxPixels: 1e10,
        crs: 'EPSG:4326', // Use WGS84 to ensure consistent area calculation
      });

      const areaSqM = stats.get('sum');
      return areaSqM;
    };

    // Calculate cropland area for 2003
    const areaSqM_2003 = await ee.data.computeValue(getCroplandArea(year1, africa));

    if (areaSqM_2003 === null) {
      console.log(`No MODIS land cover image found for ${year1}.`);
      console.log("C1");
      return;
    }
    if (areaSqM_2003 === 0) {
      console.log(`No valid cropland pixels found for ${year1} after masking.`);
      console.log("C2");
      return;
    }

    const areaSqKm_2003 = areaSqM_2003 / 1e6;

    // Calculate cropland area for 2019
    const areaSqM_2019 = await ee.data.computeValue(getCroplandArea(year2, africa));

    if (areaSqM_2019 === null) {
      console.log(`No MODIS land cover image found for ${year2}.`);
      console.log("C1");
      return;
    }
    if (areaSqM_2019 === 0) {
      console.log(`No valid cropland pixels found for ${year2} after masking.`);
      console.log("C2");
      return;
    }

    const areaSqKm_2019 = areaSqM_2019 / 1e6;

    // 4. Calculation
    const area_change_sq_km = areaSqKm_2019 - areaSqKm_2003;

    // 5. Validation & Final Answer
    if (areaSqKm_2003 === null || areaSqKm_2019 === null || isNaN(area_change_sq_km)) {
      console.log("Calculation resulted in invalid values.");
      console.log("C3");
      return;
    }

    console.log(`Cropland area in ${year1}: ${areaSqKm_2003.toFixed(2)} sq km`);
    console.log(`Cropland area in ${year2}: ${areaSqKm_2019.toFixed(2)} sq km`);
    console.log(`Increase: ${area_change_sq_km.toFixed(2)} sq km`);
    console.log(`Threshold: ${threshold_sq_km} sq km`);

    if (area_change_sq_km > threshold_sq_km) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred during the analysis:", error);
    if (error.message.includes("Image.select")) {
      console.log("D"); // Likely incorrect band name
    } else if (error.message.includes("Collection.filter")) {
      console.log("D"); // Likely incorrect collection or filter
    } else {
      console.log("D"); // General error or memory issue
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
